mapper.select:
SELECT COUNT(*)
FROM TB_FEED_LIKE
WHERE FEED_ID = #{feedId}
  AND USER_ID = #{userId}

mapper.update:
UPDATE TB_FEED
SET FEED_LIKES = FEED_LIKES + 1
WHERE FEED_ID = #{feedId}

UPDATE TB_FEED
SET FEED_LIKES = CASE WHEN FEED_LIKES > 0 THEN FEED_LIKES - 1 ELSE 0 END
WHERE FEED_ID = #{feedId}

mapper.select:
SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
FROM TB_COMMENT_LIKE
WHERE COMMENT_ID = #{commentId}
  AND USER_ID = #{userId}

mapper.update:
UPDATE TB_FEED_COMMENT
SET COMMENT_LIKES = COMMENT_LIKES + 1
WHERE COMMENT_ID = #{commentId}

mapper.select:
SELECT COUNT(*)
FROM TB_COMMENT_LIKE
WHERE COMMENT_ID = #{commentId}

mapper.update:
UPDATE TB_FEED
SET FEED_VIEWS = FEED_VIEWS + 1
WHERE FEED_ID = #{feedId}

UPDATE TB_FEED_COMMENT
SET COMMENT_CONTENT = #{commentContent}
WHERE COMMENT_ID = #{commentId}
  AND COMMENT_DELETED_FLAG = 0

UPDATE TB_FEED_COMMENT
SET COMMENT_DELETED_FLAG = 1
WHERE COMMENT_ID = #{commentId}

UPDATE TB_FEED
SET FEED_DELETED_FLAG = 1
WHERE FEED_ID = #{feedId}

UPDATE TB_FEED SET FEED_TITLE = #{params.feedTitle}, FEED_CONTENT = #{params.feedContent},
FEED_IMAGE_PATH = #{imagePath},
UPDATED_DATE = SYSDATE WHERE FEED_ID = #{params.feedId} AND USER_ID = #{params.userId}
